defmodule Spatex.Reference do
  @moduledoc false
  # Test-only helper for the PySAL oracle suite.
  #
  # Fixtures under test/reference/fixtures/ are generated by test/reference/*.py (see
  # test/reference/README.md) and committed; CI never runs Python. This module loads them and
  # compares Spatex results against them.
  #
  # Non-finite floats are not valid JSON, so the generators encode them as the strings "nan",
  # "inf" and "-inf". `load!/1` decodes them to the atoms `:nan`, `:inf` and `:neg_inf`.
  # Consequently no *string* datum in a fixture (for example an id) may equal one of those
  # three markers.

  @dir Path.expand("../../reference/fixtures", __DIR__)

  @doc "Absolute path of a fixture given its path relative to test/reference/fixtures."
  @spec fixture_path(Path.t()) :: Path.t()
  def fixture_path(rel), do: Path.expand(rel, @dir)

  @doc "Reads and decodes a fixture (path relative to test/reference/fixtures)."
  @spec load!(Path.t()) :: term()
  def load!(rel) do
    rel |> fixture_path() |> File.read!() |> Jason.decode!() |> decode_markers()
  end

  defp decode_markers("nan"), do: :nan
  defp decode_markers("inf"), do: :inf
  defp decode_markers("-inf"), do: :neg_inf
  defp decode_markers(list) when is_list(list), do: Enum.map(list, &decode_markers/1)

  defp decode_markers(map) when is_map(map),
    do: Map.new(map, fn {k, v} -> {k, decode_markers(v)} end)

  defp decode_markers(other), do: other

  @doc """
  Asserts that `actual` matches `expected` within `tol`.

  Numbers compare with `abs(a - e) <= tol * max(1.0, abs(e))` (absolute for small values,
  relative for large ones). `:nan`, `:inf` and `:neg_inf` match only themselves. Lists must have
  equal length, maps equal key sets, and any other term must be `===`. On mismatch raises
  `ExUnit.AssertionError` naming the path of the first mismatching element, such as
  `transforms.R.lag[1]`.
  """
  @spec assert_close(term(), term(), number()) :: :ok
  def assert_close(actual, expected, tol) do
    case compare(actual, expected, tol, "") do
      :ok ->
        :ok

      {:error, path, reason} ->
        raise ExUnit.AssertionError,
          message: "mismatch at #{if path == "", do: "(root)", else: path}: #{reason}"
    end
  end

  defp compare(a, e, tol, path) when is_number(a) and is_number(e) do
    if abs(a - e) <= tol * max(1.0, abs(e)),
      do: :ok,
      else: {:error, path, "expected #{inspect(e)}, got #{inspect(a)} (tol #{tol})"}
  end

  defp compare(a, e, tol, path) when is_list(a) and is_list(e) do
    if length(a) == length(e) do
      a
      |> Enum.zip(e)
      |> Enum.with_index()
      |> first_error(fn {{x, y}, i} -> compare(x, y, tol, "#{path}[#{i}]") end)
    else
      {:error, path, "length #{length(a)} != expected length #{length(e)}"}
    end
  end

  defp compare(a, e, tol, path) when is_map(a) and is_map(e) do
    keys = e |> Map.keys() |> Enum.sort()

    if a |> Map.keys() |> Enum.sort() == keys do
      first_error(keys, fn k ->
        compare(Map.fetch!(a, k), Map.fetch!(e, k), tol, join(path, k))
      end)
    else
      {:error, path,
       "keys #{inspect(a |> Map.keys() |> Enum.sort())} != expected #{inspect(keys)}"}
    end
  end

  defp compare(a, e, _tol, path) do
    if a === e, do: :ok, else: {:error, path, "expected #{inspect(e)}, got #{inspect(a)}"}
  end

  defp first_error(enum, fun) do
    Enum.find_value(enum, :ok, fn item ->
      case fun.(item) do
        :ok -> nil
        error -> error
      end
    end)
  end

  defp join("", key), do: to_string(key)
  defp join(path, key), do: "#{path}.#{key}"

  @fixture_atoms ~w(o r b d v directed two_sided greater lesser raise clique clc bjc)a

  @doc """
  Converts a fixture string option (transform, alternative, coincident) to an atom.

  Uses an explicit allow-list instead of `String.to_existing_atom/1`, whose result depends
  on which modules happen to be loaded when a test runs.
  """
  def fixture_atom(string) when is_binary(string) do
    Enum.find(@fixture_atoms, &(Atom.to_string(&1) == string)) ||
      raise ArgumentError, "unexpected fixture option #{inspect(string)}"
  end
end
